    25→/// An error occurred while validating a gossip data column.
    26→#[derive(Debug)]
    27→pub enum GossipDataColumnError {
    28→    /// There was an error whilst processing the data column. It is not known if it is
    29→    /// valid or invalid.
    30→    ///
    31→    /// ## Peer scoring
    32→    ///
    33→    /// We were unable to process this data column due to an internal error. It's
    34→    /// unclear if the data column is valid.
    35→    BeaconChainError(Box<BeaconChainError>),
    36→    /// The proposal signature in invalid.
    37→    ///
    38→    /// ## Peer scoring
    39→    ///
    40→    /// The data column is invalid and the peer is faulty.
    41→    ProposalSignatureInvalid,
    42→    /// The proposal_index corresponding to data column.beacon_block_root is not known.
    43→    ///
    44→    /// ## Peer scoring
    45→    ///
    46→    /// The data column is invalid and the peer is faulty.
    47→    UnknownValidator(u64),
    48→    /// The provided data column is not from a later slot than its parent.
    49→    ///
    50→    /// ## Peer scoring
    51→    ///
    52→    /// The data column is invalid and the peer is faulty.
    53→    IsNotLaterThanParent {
    54→        data_column_slot: Slot,
    55→        parent_slot: Slot,
    56→    },
    57→    /// The kzg verification failed.
    58→    ///
    59→    /// ## Peer scoring
    60→    ///
    61→    /// The data column sidecar is invalid and the peer is faulty.
    62→    InvalidKzgProof(kzg::Error),
    63→    /// The column was gossiped over an incorrect subnet.
    64→    ///
    65→    /// ## Peer scoring
    66→    ///
    67→    /// The column is invalid or the peer is faulty.
    68→    InvalidSubnetId { received: u64, expected: u64 },
    69→    /// The column sidecar is from a slot that is later than the current slot (with respect to the
    70→    /// gossip clock disparity).
    71→    ///
    72→    /// ## Peer scoring
    73→    ///
    74→    /// Assuming the local clock is correct, the peer has sent an invalid message.
    75→    FutureSlot {
    76→        message_slot: Slot,
    77→        latest_permissible_slot: Slot,
    78→    },
    79→    /// The sidecar corresponds to a slot older than the finalized head slot.
    80→    ///
    81→    /// ## Peer scoring
    82→    ///
    83→    /// It's unclear if this column is valid, but this column is for a finalized slot and is
    84→    /// therefore useless to us.
    85→    PastFinalizedSlot {
    86→        column_slot: Slot,
    87→        finalized_slot: Slot,
    88→    },
    89→    /// The pubkey cache timed out.
    90→    ///
    91→    /// ## Peer scoring
    92→    ///
    93→    /// The column sidecar may be valid, this is an internal error.
    94→    PubkeyCacheTimeout,
    95→    /// The proposer index specified in the sidecar does not match the locally computed
    96→    /// proposer index.
    97→    ///
    98→    /// ## Peer scoring
    99→    ///
   100→    /// The column is invalid and the peer is faulty.
   101→    ProposerIndexMismatch { sidecar: usize, local: usize },
   102→    /// The provided columns's parent block is unknown.
   103→    ///
   104→    /// ## Peer scoring
   105→    ///
   106→    /// We cannot process the columns without validating its parent, the peer isn't necessarily faulty.
   107→    ParentUnknown { parent_root: Hash256 },
   108→    /// The column conflicts with finalization, no need to propagate.
   109→    ///
   110→    /// ## Peer scoring
   111→    ///
   112→    /// It's unclear if this column is valid, but it conflicts with finality and shouldn't be
   113→    /// imported.
   114→    NotFinalizedDescendant { block_parent_root: Hash256 },
   115→    /// Invalid kzg commitment inclusion proof
   116→    ///
   117→    /// ## Peer scoring
   118→    ///
   119→    /// The column sidecar is invalid and the peer is faulty
   120→    InvalidInclusionProof,
   121→    /// A column has already been seen for the given `(sidecar.block_root, sidecar.index)` tuple
   122→    /// over gossip or no gossip sources.
   123→    ///
   124→    /// ## Peer scoring
   125→    ///
   126→    /// The peer isn't faulty, but we do not forward it over gossip.
   127→    PriorKnown {
   128→        proposer: u64,
   129→        slot: Slot,
   130→        index: ColumnIndex,
   131→    },
   132→    /// A column has already been processed from non-gossip source and have not yet been seen on
   133→    /// the gossip network.
   134→    /// This column should be accepted and forwarded over gossip.
   135→    PriorKnownUnpublished,
   136→    /// Data column index must be between 0 and `NUMBER_OF_COLUMNS` (exclusive).
   137→    ///
   138→    /// ## Peer scoring
   139→    ///
   140→    /// The column sidecar is invalid and the peer is faulty
   141→    InvalidColumnIndex(u64),
   142→    /// Data column not expected for a block with empty kzg commitments.
   143→    ///
   144→    /// ## Peer scoring
   145→    ///
   146→    /// The column sidecar is invalid and the peer is faulty
   147→    UnexpectedDataColumn,
   148→    /// The data column length must be equal to the number of commitments, otherwise the
   149→    /// sidecar is invalid.
   150→    ///
   151→    /// ## Peer scoring
   152→    ///
   153→    /// The column sidecar is invalid and the peer is faulty
   154→    InconsistentCommitmentsLength {
   155→        cells_len: usize,
   156→        commitments_len: usize,
   157→    },
   158→    /// The data column length must be equal to the number of proofs, otherwise the
   159→    /// sidecar is invalid.
   160→    ///
   161→    /// ## Peer scoring
   162→    ///
   163→    /// The column sidecar is invalid and the peer is faulty
   164→    InconsistentProofsLength { cells_len: usize, proofs_len: usize },
   165→}
