   290→/// Wrapper over a `DataColumnSidecar` for which we have completed kzg verification.
   291→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   292→#[derivative(PartialEq, Eq)]
   293→#[ssz(struct_behaviour = "transparent")]
   294→pub struct KzgVerifiedDataColumn<E: EthSpec> {
   295→    data: Arc<DataColumnSidecar<E>>,
   296→}
   297→
   298→impl<E: EthSpec> KzgVerifiedDataColumn<E> {
   299→    pub fn new(
   300→        data_column: Arc<DataColumnSidecar<E>>,
   301→        kzg: &Kzg,
   302→    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
   303→        verify_kzg_for_data_column(data_column, kzg)
   304→    }
   305→
   306→    /// Mark a data column as KZG verified. Caller must ONLY use this on columns constructed
   307→    /// from EL blobs.
   308→    pub fn from_execution_verified(data_column: Arc<DataColumnSidecar<E>>) -> Self {
   309→        Self { data: data_column }
   310→    }
   311→
   312→    /// Create a `KzgVerifiedDataColumn` from `DataColumnSidecar` for testing ONLY.
   313→    pub(crate) fn __new_for_testing(data_column: Arc<DataColumnSidecar<E>>) -> Self {
   314→        Self { data: data_column }
   315→    }
   316→
   317→    pub fn from_batch_with_scoring(
   318→        data_columns: Vec<Arc<DataColumnSidecar<E>>>,
   319→        kzg: &Kzg,
   320→    ) -> Result<Vec<Self>, (Option<ColumnIndex>, KzgError)> {
   321→        verify_kzg_for_data_column_list(data_columns.iter(), kzg)?;
   322→        Ok(data_columns
   323→            .into_iter()
   324→            .map(|column| Self { data: column })
   325→            .collect())
   326→    }
   327→
   328→    pub fn to_data_column(self) -> Arc<DataColumnSidecar<E>> {
   329→        self.data
   330→    }
   331→    pub fn as_data_column(&self) -> &DataColumnSidecar<E> {
   332→        &self.data
   333→    }
   334→    /// This is cheap as we're calling clone on an Arc
   335→    pub fn clone_data_column(&self) -> Arc<DataColumnSidecar<E>> {
   336→        self.data.clone()
   337→    }
   338→
   339→    pub fn index(&self) -> ColumnIndex {
   340→        self.data.index
   341→    }
   342→}
